<?php

namespace App\Models;

use App\Models\Concerns\BelongsToWorkspace;
use App\Models\Concerns\GuardsSriRetention;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Credit note generated when voiding an invoice with registered payments.
 *
 * Multi-tenant: uses BelongsToWorkspace for automatic scoping.
 * Auto-generated by InvoiceService::void() when the invoice has amount_paid > 0.
 */
class CreditNote extends Model
{
    use HasFactory, BelongsToWorkspace, SoftDeletes, GuardsSriRetention;

    protected $fillable = [
        'workspace_id',
        'invoice_id',
        'credit_note_number',
        'issued_at',
        'reason',
        'amount',
        'status',
        'created_by',
        // SRI authorization
        'sri_sequence_number',
        'sri_clave_acceso',
        'sri_authorization_number',
        'sri_authorization_date',
        'sri_status',
        'sri_xml',
        'sri_environment',
        'sri_submission_attempts',
        'sri_last_error',
        'sri_error',
        'sri_last_attempt_at',
    ];

    protected $casts = [
        'issued_at' => 'date',
        'amount'    => 'decimal:2',
        'sri_authorization_date'  => 'datetime',
        'sri_submission_attempts' => 'integer',
        'sri_error'           => 'array',
        'sri_last_attempt_at' => 'datetime',
    ];

    /**
     * Internal SRI artifacts that must not leak through serialization.
     */
    protected $hidden = [
        'sri_xml',
        'sri_last_error',
    ];

    public function invoice(): BelongsTo
    {
        return $this->belongsTo(Invoice::class, 'invoice_id');
    }

    public function creator(): BelongsTo
    {
        return $this->belongsTo(Doctor::class, 'created_by');
    }
}
